<?php $pageTitle='Estoque'; require_once __DIR__.'/../../includes/header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$produto=(int)$_POST['produto_id'];$tipo=$_POST['tipo'];$qtd=(float)$_POST['quantidade'];$obs=trim($_POST['observacao']??'');$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO movimentacoes_estoque(produto_id,tipo,quantidade,observacao,usuario_id) VALUES(?,?,?,?,?)')->execute([$produto,$tipo,$qtd,$obs,$_SESSION['user']['id']]);$delta=$tipo==='ENTRADA'?$qtd:-$qtd;$pdo->prepare('UPDATE produtos SET estoque_atual=estoque_atual+? WHERE id=?')->execute([$delta,$produto]);$pdo->commit();flash('ok','Movimentação registrada.');}catch(Throwable $e){$pdo->rollBack();flash('err',$e->getMessage());}header('Location:index.php');exit;}
$produtos=$pdo->query('SELECT * FROM produtos WHERE status="ATIVO" ORDER BY nome')->fetchAll();$movs=$pdo->query('SELECT m.*,p.nome produto,u.nome usuario FROM movimentacoes_estoque m JOIN produtos p ON p.id=m.produto_id LEFT JOIN usuarios u ON u.id=m.usuario_id ORDER BY m.id DESC LIMIT 50')->fetchAll(); ?>
<div class="panel mb-3"><div class="panel-title"><h3>Movimentar estoque</h3></div><form method="post" class="row g-3"><div class="col-md-4"><label>Produto</label><select name="produto_id" class="form-select" required><?php foreach($produtos as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' - '.$p['nome'].' ('.$p['estoque_atual'].')')?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Tipo</label><select name="tipo" class="form-select"><option>ENTRADA</option><option>SAIDA</option><option>AJUSTE</option></select></div><div class="col-md-2"><label>Quantidade</label><input name="quantidade" type="number" step="0.01" class="form-control" required></div><div class="col-md-4"><label>Observação</label><input name="observacao" class="form-control"></div><div class="col-12"><button class="btn btn-dark">Registrar</button></div></form></div>
<div class="panel"><div class="panel-title"><h3>Últimas movimentações</h3></div><div class="table-responsive"><table class="table"><thead><tr><th>Data</th><th>Produto</th><th>Tipo</th><th>Qtd.</th><th>Observação</th><th>Usuário</th></tr></thead><tbody><?php foreach($movs as $m):?><tr><td><?=date('d/m/Y H:i',strtotime($m['criado_em']))?></td><td><?=e($m['produto'])?></td><td><?=e($m['tipo'])?></td><td><?=e($m['quantidade'])?></td><td><?=e($m['observacao'])?></td><td><?=e($m['usuario']??'-')?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>